246: struct uio_info_t *uio_find_by_uio_name (char *uio_name)
247: {
248: 	struct uio_info_t *info = NULL, **list, **uio_list;
249: 	char *name;
250: 
251: 	if (!uio_name)
252: 		return NULL;
253: 
254: 	uio_list = uio_find_devices ();
255: 	if (!uio_list)
256: 		return NULL;
257: 
258: 	for (list = uio_list; *list; list++)
259: 	{
260: 		struct uio_info_t *candidate = *list;
261: 
262: 		name = uio_get_name (candidate);
263: 
264: 		if (!strcmp (name, uio_name)) {
265: 			info = candidate;
266: 			break;
267: 		}
268: 	}
269: 	free (uio_list);
270: 
271: 	return info;

344: int uio_open_fix (struct uio_info_t* info, void *ptr)
345: {
346: 	int fd, i;
347: 
348: 	if (!info)
349: 	{
350: 		errno = EINVAL;
351: 		g_warning (_("uio_open: %s\n"), g_strerror (errno));
352: 		return -1;
353: 	}
354: 
355: 	fd = open (info->devname, O_RDWR);
356: 	if (fd < 0)
357: 	{
358: 		g_warning (_("open: %s\n"), g_strerror (errno));
359: 		return -1;
360: 	}
361: 
362: 	for (i = 0; i < info->maxmap; i++)
363: 	{
364: 		info->maps [i].map = mmap (ptr, info->maps [i].size,
365: 					   PROT_READ | PROT_WRITE,
366: 					   MAP_SHARED, fd, i * getpagesize());
367: 		if (info->maps[i].map == MAP_FAILED) {
368: 			while (--i >= 0)
369: 				uio_unmap (&info->maps [i]);
370: 			g_warning (_("mmap: %s\n"), g_strerror (errno));
371: 			return -1;
372: 		}
373: 		if (ptr)
374: 			ptr += info->maps [i].size;
375: 	}
376: 	info->fd = fd;
377: 
378: 	return 0;

