142: static inline uint32_t make_mask(uint32_t width, uint32_t offset) {
143:     // Cubre también width > 32 de forma defensiva
144:     if (width >= 32) return 0xFFFFFFFFu;
145:     // Asegura el 1 como unsigned de 32 bits y evita UB
146:     return ((uint32_t{1} << width) - 1u) << offset;
147: }
