149: uint32_t ReadPRBS::_isolateBitsForRead(uint32_t value, uint32_t bitWidth, uint8_t bitOffset) {
150:     const uint32_t mask = make_mask(bitWidth, bitOffset);
151:     return (value & mask) >> bitOffset;
152: }
