694: 								fsm_state_ic <= sending_command;
695: 							end if;
696: 
697: 						elsif (control_fifoctrl(0) = '1' or control_lpgbtctrl(0) = '1') and control_strobe = '1' then -- Read request to lpgbt
698: 							-- Clear previous errors
699: 							status_timeout_error(0) <= '0';
700: 							status_parity_error(0)  <= '0';
701: 							if status_ready_flag(0) = '1' then
702: 								IC_tx_start_read_s <= '1'; -- read command to lpgbt
703: 								control_nb_read_ic <= x"0001"; --only one byte allowed
704: 								lpgbt_resp_timeout := 100000000;
