715: 					when waiting_resp =>
716: 						IC_tx_start_write_s <= '0';
717: 						IC_tx_start_read_s  <= '0';
718: 						lpgbt_resp_timeout  := lpgbt_resp_timeout - 1;
719: 						if status_empty_flag(0) = '0' and (data_rx_data_FIFO = x"E0" or data_rx_data_FIFO = x"E1") then -- start reading FIFO
720: 							IC_rx_rd_s               <= '1'; --start pulling from FIFO
721: 							FIFO_cnt                 <= 0;
722: 							next_FIFO_byte_available <= 0;
723: 							parity_check             <= x"00";
724: 							lpgbt_resp_timeout       := 100000000;
725: 							fsm_state_ic             <= reading_FIFO;
726: 						elsif lpgbt_resp_timeout = 0 then -- waiting during 1 second, rise error flag
727: 							status_timeout_error(0) <= '1';
728: 							fsm_state_ic            <= finish;
729: 						end if;
730: 
731: 					when reading_FIFO => -- reading all the bytes on the fifo
732: 
733: 						lpgbt_resp_timeout := lpgbt_resp_timeout - 1;
734: 						IC_rx_rd_s         <= '0'; -- wait until next byte is available
735: 
736: 						if status_empty_flag(0) = '1' then -- need to wait until empy flag goes '1' again, before reading next byte					
737: 							next_FIFO_byte_available <= 1;
