749: 								if data_rx_data_FIFO = x"0" then
750: 									fsm_state_ic <= finish;
751: 								end if;
752: 							elsif FIFO_cnt = 6 then -- get the data
753: 								data_rx_data <= data_rx_data_FIFO;
754: 							elsif FIFO_cnt = 7 then -- check parity byte
755: 								if parity_check = data_rx_data_FIFO then
756: 									interrupt_flags_ic_resp(0) <= '1'; -- trigger interrupt
757: 								else
758: 									status_parity_error(0) <= '1';
759: 								end if;
760: 								fsm_state_ic <= finish;
761: 							end if;
762: 							next_FIFO_byte_available <= 0;
763: 							FIFO_cnt <= FIFO_cnt + 1;
764: 
765: 						elsif lpgbt_resp_timeout = 0 then -- waiting during 1 second, rise error flag
766: 							status_timeout_error(0) <= '1';
767: 							fsm_state_ic            <= finish;
768: 						end if;
769: 
770: 					when finish =>
771: 						IC_rx_rd_s   <= '0';
772: 						fsm_state_ic <= idle;
773: 
774: 				end case;
775: 
776: 			else                        -- Multiple read/writes. PS manages FIFO and parity bit
777: 				IC_rx_rd_s          <= control_fifoctrl(0) and control_strobe;
